    "home.title.line1": "Fàs àite sam bith,",
    "home.title.line2": "san dòigh agad fhèin.",
    "home.intro": "'S e companach sàmhach a th' ann am Patch & Pot dhaibhsan a tha a' fàs ann an àiteachan beaga — mìosachan, faire air plàighean, leabharlann lusan agus gàrradh pearsanta airson biadh is flùraichean, air a chur an òrdugh dhan àite air feadh an t-saoghail anns a bheil thu.",
    "home.cta.guide": "Seall stiùireadh {month}",
    "home.section.eyebrow": "A-staigh ann am Patch & Pot",
    "home.section.title": "Bhon phoit chun a' phlàta — fàs àite sam bith, san dòigh agad fhèin.",
    "home.section.body": "Comhairle a tha air a dhèanamh dhad sgìre fhèin, air a sgrìobhadh dhan àite is dhan mhìos cheart agad. Co-dhiù a tha thu a' gàirneilearachd air bhalcon san naoidheamh-làr ann an Singeapòr no air uinneig ann an Reiceabhic, gheibh thu mìosachan, obraichean is rabhaidhean a fhreagras air do shuidheachadh.",
    "home.quote.eyebrow": "Nota mu fhoighidinn",
    "home.quote.body": "„Chan eil lusan a' leughadh mhìosachan — ach tha iad a' faireachdainn càite a bheil thu a' fuireach. 'S i a' chomhairle ghàirneilearachd as fheumail an tè a chaidh a sgrìobhadh dhan mhìos agad, na do dh'àite fhèin.“",
