    "home.intro": "Patch & Pot je tichý společník pro ty, kteří pěstují v malých prostorech — měsíční kalendář, monitoring škůdců, knihovna rostlin a osobní zahrada pro jídlo i květiny, upravené pro místo na světě, kde se nacházíte.",
