    "home.section.body": "Rady upravené pro váš region, napsané pro vaše přesné místo a měsíc. Ať pěstujete na balkoně v devátém patře v Singapuru nebo na parapetu v Reykjavíku, dostanete kalendář, úkoly a varování před škůdci, které se hodí k vašim podmínkám.",
