    "mc.tagline.pest-control": "Εντοπίστε, προλάβετε και αντιμετωπίστε τα συνηθισμένα έντομα σε γλάστρες και μικρούς κήπους — με προτεραιότητα στα βιολογικά.",
    "mc.title.plant-care": "Φροντίδα Φυτών",
    "mc.tagline.plant-care": "Πότισμα, λίπανση, φως, αλλαγή γλάστρας και ο εποχιακός ρυθμός φροντίδας φυτών σε γλάστρες.",
    "mc.title.seasonal-planting": "Εποχιακή Φύτευση",
    "mc.tagline.seasonal-planting": "Διαβάστε τον χρόνο σαν κηπουρός — παράθυρα σποράς, διαδοχή και επέκταση κάθε εποχής.",
    "mc.title.dahlia": "Ντάλιες",
    "mc.tagline.dahlia": "Μεγάλες, γενναιόδωρες, αστέρες του τέλους καλοκαιριού — από κόνδυλους στο βάζο.",
    "mc.title.aster": "Αστέρια",
    "mc.tagline.aster": "Αγαπημένα από τους επικονιαστές, αστέρια τέλους σεζόν — για μια τελευταία έκρηξη πριν τον παγετό.",
    "mc.title.rose": "Τριαντάφυλλα",
    "mc.tagline.rose": "Από γυμνόριζο τριαντάφυλλο βεράντας μέχρι αρωματικό αναρριχητικό — η βασίλισσα του κήπου, απλοποιημένη.",
    "mc.title.tulip": "Τουλίπες",
    "mc.tagline.tulip": "Φυτέψτε αργά, φυτέψτε βαθιά, στρωματοποιήστε για μια μακρά επίδειξη — ο πιο γενναιόδωρος βολβός στον κήπο.",
    "mc.title.sunflower": "Ηλιοτρόπια",
    "mc.tagline.sunflower": "Σπείρτε μια φορά, παρακολουθήστε τη σεζόν να κυλά — από γίγαντες μέχρι λεπτούς διακλαδωμένους πολυκέφαλους.",
    "mc.title.peony": "Παιώνιες",
    "mc.tagline.peony": "Μακρόβιες, αρωματικές, σχεδόν απίστευτα γενναιόδωρες — η ανταμοιβή του υπομονετικού κηπουρού.",
    "mc.title.cosmos": "Κόσμος",
    "mc.tagline.cosmos": "Το πιο εύκολο, μακράς ανθοφορίας, ετήσιο φυτό κοπής στον πλανήτη.",
    "mc.title.zinnia": "Ζίνιες",
    "mc.tagline.zinnia": "Θερμόφιλες, κάθε χρώματος, ανανεώνονται με το κόψιμο — το μηχάνημα των ανθοδεσμών.",
    "mc.title.lavender": "Λεβάντα",
    "mc.tagline.lavender": "Ανθεκτική στην ξηρασία, μαγνήτης για μέλισσες, αρωματική — το μεσογειακό κλασικό που μισεί την υπερβολική αγάπη.",
    "mc.title.lily": "Κρίνα",
